Lemma read_bits_ok : forall d nb, 0 <= nb < 32 ->
  read_bits d nb = Ok (Z.land (Z.shiftr (bd_cont d) ((u32 (64 - bd_bits d - nb)) mod 64)) (2^nb - 1), skip_bits d nb).
