(* [comment removed for export] *)
Definition dres (DST dcap : Z) (r : res (list Z)) (m2 : fmem) (a4v : Z) : Prop :=
  match r with
  | Ok l => a4v = zlen l /\ exists junk, u8arr psegs m2 DST (map (Z_to_bv 8) l ++ junk) /\ zlen junk = dcap - zlen l
  | Err e => a4v = - e /\ 0 < e < 120
  | Ub | NoFuel => False
  end.

Section SI.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x23 x24 x25 x26 x27 : word).          (* [comment removed for export] *)
  Variables (m0 : fmem) (S DT DST dcap lo : Z) (bs : list Z) (dt : dtable) (fmw : word) (jd j1 j2 jb : list byte).
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Notation tl := (dt_tableLog dt).
  (* [comment removed for export] *)
  Hypothesis FR2 : rw_cells psegs m0 (SP + 16) [CB 16 j2].
  Hypothesis FR1 : rw_cells psegs m0 (SP + 32) [CB 16 j1].
  Hypothesis FRB : rw_cells psegs m0 (SP + 48) [CB 40 jb].
  (* [comment removed for export] *)
  Hypothesis DTH : rw_cells psegs m0 DT [C2 (Z_to_bv 64 tl); C2 fmw].
  Hypothesis TBB : bytes_at psegs m0 (DT + 4) (concat (map fse_cell_bytes (dt_cells dt))).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HCELLS : zlen (dt_cells dt) = 2^tl.
  Hypothesis HCOK : cells_ok tl (dt_cells dt).
  (* [comment removed for export] *)
  Hypothesis SRC : bytes_at psegs m0 S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis OUTA : u8arr psegs m0 DST jd.
  Hypothesis LJD : zlen jd = dcap.
  Hypothesis STK : stk psegs m0 lo SP.
  Hypothesis MI : mem_inv psegs m0.
  (* [comment removed for export] *)
  Hypothesis LOSP : lo <= SP.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP + 160 <= 2^47.
  Hypothesis HS : 8 <= S /\ S + zlen bs <= lo.
  Hypothesis HDT : 0 < DT /\ DT mod 4 = 0 /\ DT + 4 + 4 * 2^tl <= lo.
  Hypothesis HDST : 3 <= DST /\ DST + dcap <= lo /\ 0 <= dcap <= 255.
  Hypothesis DJ1 : DST + dcap <= DT \/ DT + 4 + 4 * 2^tl <= DST.
  Hypothesis DJ2 : DST + dcap <= S \/ S + zlen bs <= DST.
  Hypothesis DJ3 : DT + 4 + 4 * 2^tl <= S \/ S + zlen bs <= DT.

  (* [comment removed for export] *)
  Notation TX mm a4v y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31 :=
    (MS (mkR y1 sp gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 (Z_to_bv 64 a4v) y15 y16 y17 y18 y19 y20 y21 y22 y23 x24 x25 x26 x27
             y28 y29 y30 y31)
        F (Z_to_bv 64 0x1be74) fc None mm (seg_rom psegs)).

  Definition safe_K (r : res (list Z)) : Prop :=
    forall m2 a4v (y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31 : word),
      munch [(SP + 16, SP + 88); (DST, DST + dcap)] m0 m2 -> wmono psegs m0 m2 -> mem_inv psegs m2 -> stk psegs m2 lo SP ->
      dres DST dcap r m2 a4v ->
      evt psegs POST (TX m2 a4v y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31).

  Notation WF := [(SP + 16, SP + 88); (DST, DST + dcap)].

  (* [comment removed for export] *)
  Lemma safe_main : forall m1 d3 s1 s2 r (wc wb wp : word) (jp : list byte) (x8 x9 x18 x22 x30 x31 : word) (P2 P3 : Z),
    P2 = S + bd_ptr d3 -> P3 = S ->
    (let! x := main_loop bs dt dcap false (Datatypes.S (Z.to_nat dcap)) (mkDec [] s1 s2 d3) in
     tail_loop bs dt dcap false (Datatypes.S (Z.to_nat dcap)) x) = r -> res_ok r ->
    bitd_ok bs d3 -> bd_bits d3 <= 64 -> bd_zero d3 = false ->
    rw_cells psegs m1 (SP + 16) [C8 (Z_to_bv 64 s2); C8 (Z_to_bv 64 (DT + 4))] ->
    rw_cells psegs m1 (SP + 32) [C8 (Z_to_bv 64 s1); C8 (Z_to_bv 64 (DT + 4))] ->
    rw_cells psegs m1 (SP + 48) [C8 wc; C4 wb; CB 4 jp; C8 wp; C8 (Z_to_bv 64 S); C8 (Z_to_bv 64 (S + 8))] ->
    hk (bytes_at psegs m1 (DT + 4) (concat (map fse_cell_bytes (dt_cells dt)))) ->
    bytes_at psegs m1 S (map (Z_to_bv 8) bs) -> u8arr psegs m1 DST jd ->
    munch WF m0 m1 -> wmono psegs m0 m1 -> mem_inv psegs m1 -> stk psegs m1 lo SP -> safe_K r ->
    evt psegs POST (MS (mkR (Z_to_bv 64 0x1bedc) sp gp tp (Z_to_bv 64 (bd_bits d3)) (Z_to_bv 64 s2) (Z_to_bv 64 s1) x8 x9
                            (Z_to_bv 64 (S + 8)) (Z_to_bv 64 BIT_MASK_TAB) (Z_to_bv 64 P2) (Z_to_bv 64 P3)
                            (Z_to_bv 64 ZEROFILLED_F) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 (bd_cont d3)) x18
                            (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) x22 x23 x24 x25 x26 x27
                            (Z_to_bv 64 DST) (Z_to_bv 64 64) x30 x31)
