                            x17 x18 (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) x22 x23 x24 x25
                            x26 x27 x28 x29 x30 x31)
                       F (Z_to_bv 64 0x1bea4) fc None m0 (seg_rom psegs)).
